function t(key, params, fallback) {
  var i18n = window.lmxI18n;
  if (i18n && i18n.t) {
    var out = i18n.t('local-looksmax-chat.forum.' + key, params || {}, fallback);
    if (typeof out === 'string') return out;
  }
  return fallback;
}

